<?php namespace Workspace;
function clientHidden(string $name,mixed $value): void { ?><input type="hidden" name="<?= h($name) ?>" value="<?= h($value) ?>"><?php }
function clientForm(string $act,array $hidden=[]): void { formFields($act); foreach ($hidden as $k=>$v) clientHidden($k,$v); }
function clientInput(string $name,string $label,mixed $value='',string $type='text',bool $required=true): void { ?><label><?= h($label) ?><input name="<?= h($name) ?>" type="<?= h($type) ?>" value="<?= h($value) ?>" <?= $required?'required':'' ?>></label><?php }
function clientArea(string $name,string $label,mixed $value='',int $max=4000,bool $required=true): void { ?><label><?= h($label) ?><textarea name="<?= h($name) ?>" maxlength="<?= $max ?>" rows="4" <?= $required?'required':'' ?>><?= h($value) ?></textarea></label><?php }
function clientPdfOptions(array $versions): void { foreach ($versions as $v): ?><option value="<?= h($v['id'].':'.$v['revision']) ?>"><?= h($v['title'].' v'.$v['revision']) ?></option><?php endforeach; }
function clientPartyFields(array $p=[]): void { clientInput('name','Название',$p['name']??''); clientInput('registration','Регистрационные реквизиты',$p['registration']??'','text',false); clientInput('notes','Заметки',$p['notes']??'','text',false); }
function clientContactFields(array $c=[]): void { clientInput('name','Имя',$c['name']??''); clientInput('email','Почта',$c['email']??'','email'); clientInput('phone','Телефон',$c['phone']??'','tel',false); }
function clientOfferFields(array $o=[]): void { clientArea('scope','Предложение и условия',$o['scope']??''); ?><label>Валюта<select name="currency"><?php selectOptions(array_combine(CURRENCIES,CURRENCIES),$o['currency']??'RUB') ?></select></label><?php }
function clientStageFields(array $s=[]): void { clientInput('title','Этап',$s['title']??''); clientArea('scope','Объём и критерии приёмки',$s['scope']??''); clientInput('due_on','Срок',$s['due_on']??'','date'); clientInput('amount','Цена',$s?money((int)$s['amount_minor'],false):''); }
?>
<?php if (!isset($order)): ?>
<?php if(isset($freelance)) require ROOT."/views/freelance.php"; ?>
<section class="panel inset"><h2>Новый контрагент</h2><form method="post" class="formgrid"><?php clientForm('client.party'); clientPartyFields(); ?><button class="primary">Создать</button></form></section>
<section class="panel inset"><h2>Справочник контрагентов</h2><?php if (!$parties): ?><p>Контрагентов пока нет.</p><?php endif ?>
<?php foreach (array_slice($parties,0,50) as $p): ?><details><summary><?= h($p['name']) ?> · <?= h($p['registration']) ?></summary><form method="post" class="formgrid"><?php clientForm('client.party',['party_id'=>$p['id'],'version'=>$p['version']]); clientPartyFields($p); ?><button class="secondary">Сохранить</button></form>
<h3>Контактные лица</h3><?php foreach ($contacts as $c): if ((int)$c['counterparty_id']!==(int)$p['id']) continue; ?><form method="post" class="formgrid"><?php clientForm('client.contact',['party_id'=>$p['id'],'contact_id'=>$c['id'],'version'=>$c['version']]); clientContactFields($c); ?><button class="secondary">Сохранить контакт</button></form><?php endforeach ?>
<form method="post" class="formgrid"><?php clientForm('client.contact',['party_id'=>$p['id']]); clientContactFields(); ?><button class="primary">Добавить контакт</button></form></details><?php endforeach ?></section>
<section class="panel inset"><h2>Новый запрос клиента</h2><?php if ($projects&&$contacts): ?><form method="post" class="formgrid"><?php clientForm('client.request'); ?><label>Проект<select name="project_id"><?php selectOptions($projects) ?></select></label><label>Контакт<select name="contact_id"><?php foreach ($contacts as $c): ?><option value="<?= h($c['id']) ?>"><?= h($c['party_name'].' / '.$c['name'].' / '.$c['email']) ?></option><?php endforeach ?></select></label><?php clientInput('title','Название запроса'); clientArea('request_text','Потребность клиента'); ?><button class="primary">Зарегистрировать запрос</button></form><?php else: ?><p>Создайте клиентский проект, контрагента и контакт.</p><?php endif ?></section>
<section class="panel inset"><h2>Заказы</h2><?php foreach (array_slice($orders,0,50) as $o): ?><div class="splitrow"><div><a href="<?= h(url('clients',['id'=>$o['id']])) ?>"><?= h($o['title']) ?></a><small><?= h($o['client_name'].' / '.$o['project_title']) ?></small><?php if(!empty($freelanceOverdue[$o['id']])): ?><p class="notice">Просроченные счета: <?= h($freelanceOverdue[$o['id']]) ?></p><?php endif ?></div></div><?php endforeach ?><?php if (!$orders): ?><p>Запросов пока нет.</p><?php endif ?>
<?php if ($pageNo>1): ?><a href="<?= h(url('clients',['n'=>$pageNo-1])) ?>">Предыдущая страница</a><?php endif ?> <?php if (count($orders)>50||count($parties)>50): ?><a href="<?= h(url('clients',['n'=>$pageNo+1])) ?>">Следующая страница</a><?php endif ?></section>
<?php else: $oid=(int)$order['id']; ?>
<p><a href="<?= h(url('clients')) ?>">Все заказы</a> · <a href="<?= h(url('project',['id'=>$order['project_id']])) ?>"><?= h($order['project_title']) ?></a></p>
<section class="panel inset"><h2><?= h($order['title']) ?></h2><p><?= h($order['client_name'].' · '.$order['contact_name'].' · '.$order['contact_email']) ?></p><h3>Запрос клиента</h3><div class="client-text"><?= h($order['request_text']) ?></div></section>
<?php if(isset($freelance)) require ROOT.'/views/freelance.php'; ?>
<?php if (!$offers||$offers[0]['status']==='rejected'): ?><section class="panel inset"><h2>Новое предложение</h2><form method="post" class="formgrid"><?php clientForm('client.offer',['order_id'=>$oid]); clientOfferFields(); ?><button class="primary">Создать редакцию</button></form></section><?php endif ?>
<?php foreach ($offers as $offer): $locked=in_array((int)$offer['id'],array_map(fn($a)=>(int)$a['offer_id'],$freelance['agreements']??[]),true); $common=['order_id'=>$oid,'offer_id'=>$offer['id'],'version'=>$offer['version']]; ?><section class="panel inset"><h2>Предложение v<?= h($offer['revision']) ?> · <?= h(OFFER_STATES[$offer['status']]) ?></h2><p class="client-text"><?= h($offer['scope']) ?></p><p><b>Смета: <?= h(money($offer['total']).' '.$offer['currency']) ?></b></p>
<?php if ($offer['decided_at']): ?><p>Решение клиента: <?= h($offer['decision_email'].' · '.gmdate('Y-m-d H:i',$offer['decided_at'])) ?> UTC · <?= h($offer['decision_note']) ?></p><?php endif ?>
<?php if ($offer['status']==='draft'&&!$locked): ?><details><summary>Изменить предложение</summary><form method="post" class="formgrid"><?php clientForm('client.offer.edit',$common); clientOfferFields($offer); ?><button class="secondary">Сохранить</button></form></details><?php endif ?>
<?php foreach ($offer['stages'] as $s): $sid=(int)$s['id']; $latest=$s['deliveries'][0]??null; ?><article class="client-stage"><h3><?= h($s['title']) ?> · <?= h(money((int)$s['amount_minor']).' '.$offer['currency']) ?></h3><p>Срок: <?= h(displayDate($s['due_on'])) ?><?= $latest?' · '.h(DELIVERY_STATES[$latest['status']]):'' ?></p><div class="client-text"><?= h($s['scope']) ?></div>
<?php if ($offer['status']==='draft'&&!$locked): ?><details><summary>Редактировать этап</summary><form method="post" class="formgrid"><?php clientForm('client.stage',$common+['stage_id'=>$sid]); clientStageFields($s); ?><button class="secondary">Сохранить</button></form><form method="post"><?php clientForm('client.stage.remove',$common+['stage_id'=>$sid]); ?><button class="secondary">Удалить этап</button></form></details><?php endif ?>
<?php if ($offer['status']==='accepted'): ?><h4>Задачи этапа</h4><?php foreach ($s['tasks'] as $t): ?><div class="splitrow"><div><a href="<?= h(url('task',['id'=>$t['id']])) ?>"><?= h($t['title']) ?></a> · <?= h($t['state']) ?></div><?php if (!$latest): ?><form method="post"><?php clientForm('client.task',['order_id'=>$oid,'stage_id'=>$sid,'task_id'=>$t['id'],'remove'=>1]); ?><button class="secondary compact">Отвязать</button></form><?php endif ?></div><?php endforeach ?>
<?php if (!$latest && $tasks): ?><form method="post" class="inline"><?php clientForm('client.task',['order_id'=>$oid,'stage_id'=>$sid]); ?><label>Задача<select name="task_id"><?php selectOptions(array_column($tasks,'title','id')) ?></select></label><button class="secondary">Привязать</button></form><?php endif ?>
<?php foreach ($s['deliveries'] as $d): ?><div class="client-stage"><b>Сдача v<?= h($d['revision']) ?> · <?= h(DELIVERY_STATES[$d['status']]) ?></b><p class="client-text"><?= h($d['result_text']) ?></p><?php if ($d['document_id']): ?><p><a href="<?= h(url('download',['id'=>$d['document_id'],'v'=>$d['document_revision']])) ?>">PDF результата</a></p><?php endif ?><?php if ($d['decided_at']): ?><p>Решение: <?= h($d['decision_email'].' · '.gmdate('Y-m-d H:i',$d['decided_at']).' UTC · '.$d['decision_note']) ?></p><?php endif ?><?php if ($d['status']==='accepted'): ?><p>Принятый объём: <?= h($d['accepted_minutes']) ?> мин. · Согласованная цена: <?= h(money((int)$s['amount_minor']).' '.$offer['currency']) ?></p><details><summary>Записи принятых часов</summary><?php if (!$d['hours']): ?><p>Утверждённых записей на момент приёмки не было.</p><?php endif ?><?php foreach ($d['hours'] as $entry): ?><p><?= h($entry['name'].' · '.$entry['worked_on'].' · '.$entry['minutes'].' мин.') ?> · <a href="<?= h(url('task',['id'=>$entry['task_id']])) ?>">Задача</a> · <a href="<?= h(url('workload',['project'=>$order['project_id'],'week'=>$entry['week_on']])) ?>">Таймшиты недели</a></p><?php endforeach ?></details><?php endif ?></div><?php endforeach ?>
<?php if (!$latest||$latest['status']==='returned'): ?><form method="post" class="formgrid"><?php clientForm('client.deliver',['order_id'=>$oid,'stage_id'=>$sid]); clientArea('result_text','Сдаваемый результат'); ?><label>PDF результата (необязательно)<select name="document"><option value="">Без PDF</option><?php clientPdfOptions($versions) ?></select></label><button class="primary">Передать на приёмку</button></form><?php endif ?><?php endif ?></article><?php endforeach ?>
<?php if ($offer['status']==='draft'): ?><?php if(!$locked): ?><details><summary>Добавить этап сметы</summary><form method="post" class="formgrid"><?php clientForm('client.stage',$common); clientStageFields(); ?><button class="primary">Добавить</button></form></details><?php else: ?><p>Условия пакетного предложения зафиксированы.</p><?php endif ?><form method="post"><?php clientForm('client.publish',$common); ?><button class="primary">Отправить предложение клиенту</button></form><?php endif ?></section><?php endforeach ?>
<section class="panel inset"><h2>Доступ клиента к этому заказу</h2><p>Приглашение выдаётся только контакту, сохранённому в запросе. Выберите PDF, разрешённый для просмотра. Код одноразовый.</p><?php if (!empty($clientToken)): ?><label>Код приглашения<input readonly value="<?= h($clientToken) ?>"></label><a href="<?= h(url('guest.join')) ?>">Вход клиента</a><?php endif ?>
<?php if (oidcEnabled()&&$versions): ?><form method="post" class="formgrid"><?php clientForm('client.invite',['order_id'=>$oid]); ?><label>Разрешённый PDF<select name="document"><?php clientPdfOptions($versions) ?></select></label><label>Срок кода, часов<input type="number" name="hours" value="24" min="1" max="168" required></label><button class="primary">Выдать приглашение</button></form><?php else: ?><p>Настройте SkiF4er ID и загрузите доступную клиенту редакцию PDF.</p><?php endif ?>
<?php foreach ($grants as $g): ?><div class="splitrow"><span><?= h($g['email']) ?> · <?= $g['revoked_at']?'отозвано':($g['accepted_at']?($g['access_until']>time()?'активно':'доступ истёк'):($g['expires_at']>time()?'ожидает':'код истёк')) ?></span><?php if (!$g['revoked_at']): ?><form method="post"><?php clientForm('client.revoke',['order_id'=>$oid,'guest_id'=>$g['id']]); ?><button class="secondary">Отозвать</button></form><?php endif ?></div><?php endforeach ?></section>
<?php endif ?>
